1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	  rune: 25,
6	};
7	
8	const FIRST_INSURANCE_SURCHARGE = 0.1;
9	
10	interface Item {
11	  type: string;
12	}
13	
14	interface QuoteStep {
15	  op: "quote";
16	  items: Item[];
17	}
18	
19	interface Scenario {
20	  customer: { yearsWithMHPCO: number };
21	  steps: QuoteStep[];
22	}
23	
24	const itemPremium = (item: Item): number => {
25	  const base = BASE_PREMIUMS[item.type];
26	  return base + base * FIRST_INSURANCE_SURCHARGE;
27	};
28	
29	const quotePremium = (items: Item[]): number => {
30	  const itemsTotal = items.reduce((sum, item) => sum + itemPremium(item), 0);
31	  return Math.ceil(itemsTotal + PROCESSING_FEE);
32	};
33	
34	export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => {
35	  const results = scenario.steps.map((step) => ({ premium: quotePremium(step.items) }));
36	  return { results };
37	};
